import { useState } from 'react';
import Sparkline from './Sparkline';

const SOURCE_LABELS = {
  HLT: { label: 'Manual log',  color: '#8892AA', bg: 'rgba(255,255,255,0.06)',  border: 'rgba(255,255,255,0.1)' },
  WLT: { label: 'Groww live',  color: '#FBBF24', bg: 'rgba(251,191,36,0.1)',   border: 'rgba(251,191,36,0.25)' },
  SOC: { label: 'Manual log',  color: '#8892AA', bg: 'rgba(255,255,255,0.06)',  border: 'rgba(255,255,255,0.1)' },
};

const STOCK_CONFIG = {
  HLT: {
    color: '#34D399', dimColor: 'rgba(52,211,153,0.1)', borderColor: 'rgba(52,211,153,0.2)',
    icon: '❤', label: 'Health', category: 'Physical & Mental',
    greeting: (s) => s >= 7 ? `You're on fire — ${s} days straight` : s >= 3 ? `${s}-day streak. Keep going` : `Start a streak today`,
  },
  WLT: {
    color: '#FBBF24', dimColor: 'rgba(251,191,36,0.1)', borderColor: 'rgba(251,191,36,0.2)',
    icon: '◈', label: 'Wealth', category: 'Savings & Investments',
    greeting: (s) => s >= 7 ? `Compounding beautifully — ${s} days active` : s >= 3 ? `Building momentum` : `Log a wealth action today`,
  },
  SOC: {
    color: '#60A5FA', dimColor: 'rgba(96,165,250,0.1)', borderColor: 'rgba(96,165,250,0.2)',
    icon: '⬡', label: 'Social', category: 'People & Connections',
    greeting: (s) => s >= 7 ? `You're well connected — ${s} days` : s >= 3 ? `${s} days of good energy` : `Reach out to someone today`,
  },
};

const ACTIVITIES = {
  HLT: [
    { type: 'gym_session',  label: 'Gym session',    vtl: '+12', emoji: '🏋' },
    { type: 'run_walk',     label: 'Run / Walk',     vtl: '+8',  emoji: '🏃' },
    { type: 'sleep_logged', label: 'Great sleep',    vtl: '+6',  emoji: '😴' },
    { type: 'healthy_meal', label: 'Healthy meal',   vtl: '+4',  emoji: '🥗' },
  ],
  WLT: [
    { type: 'sip_active',      label: 'SIP active',        vtl: '+10', emoji: '📈' },
    { type: 'savings_added',   label: 'Added savings',     vtl: '+12', emoji: '🏦' },
    { type: 'portfolio_check', label: 'Reviewed portfolio', vtl: '+3', emoji: '👀' },
  ],
  SOC: [
    { type: 'event_attended',  label: 'Event attended',  vtl: '+10', emoji: '🎉' },
    { type: 'friend_call',     label: 'Called a friend', vtl: '+7',  emoji: '📞' },
    { type: 'networking_meet', label: 'Networking',       vtl: '+9', emoji: '🤝' },
  ],
};

export default function StockCard({ stock, onLog, onSync, animDelay = 0 }) {
  const [expanded, setExpanded]     = useState(false);
  const [logging, setLogging]       = useState(null);
  const [celebrated, setCelebrated] = useState(null);

  const cfg    = STOCK_CONFIG[stock.ticker] || STOCK_CONFIG.HLT;
  const acts   = ACTIVITIES[stock.ticker] || [];
  const isUp   = stock.direction === 'up';
  const isDown = stock.direction === 'down';
  const statusLabel = stock.status ? stock.status.charAt(0).toUpperCase() + stock.status.slice(1) : (isUp ? 'Bullish' : isDown ? 'Bearish' : 'Steady');
  const statusColor = stock.status === 'bullish' ? '#34D399' : stock.status === 'bearish' ? '#F87171' : '#8892AA';

  const handleLog = async (type) => {
    setLogging(type);
    await onLog(type);
    setCelebrated(type);
    setTimeout(() => setCelebrated(null), 800);
    setLogging(null);
    setExpanded(false);
  };

  return (
    <div
      style={{
        background: 'linear-gradient(145deg, var(--bg-card) 0%, var(--bg-elevated) 100%)',
        border: `1px solid ${expanded ? cfg.borderColor : 'var(--border)'}`,
        borderRadius: '20px', padding: '22px', cursor: 'pointer',
        transition: 'all 0.3s cubic-bezier(0.4,0,0.2,1)',
        animation: `fadeUp 0.5s ease ${animDelay}s both`,
        position: 'relative', overflow: 'hidden',
      }}
      onMouseEnter={e => { e.currentTarget.style.borderColor = cfg.borderColor; e.currentTarget.style.transform = 'translateY(-2px)'; }}
      onMouseLeave={e => { e.currentTarget.style.borderColor = expanded ? cfg.borderColor : 'var(--border)'; e.currentTarget.style.transform = 'translateY(0)'; }}
      onClick={() => setExpanded(v => !v)}
    >
      <div style={{ position:'absolute', top:-60, right:-60, width:160, height:160, borderRadius:'50%', background:cfg.color, opacity:0.05, filter:'blur(40px)', pointerEvents:'none' }}/>

      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:14 }}>
        <div style={{ display:'flex', alignItems:'center', gap:12 }}>
          <div style={{ width:42, height:42, borderRadius:13, background:cfg.dimColor, border:`1px solid ${cfg.borderColor}`, display:'flex', alignItems:'center', justifyContent:'center', fontSize:18, animation: celebrated ? 'celebrate 0.6s ease' : 'none' }}>
            {cfg.icon}
          </div>
          <div>
            <div style={{ fontFamily:'var(--font-display)', fontWeight:700, fontSize:16, color:'var(--text-primary)', letterSpacing:'0.01em' }}>{cfg.label}</div>
            <div style={{ fontSize:11, color:'var(--text-muted)', marginTop:2 }}>{cfg.category}</div>
          </div>
        </div>
        <div style={{ textAlign:'right' }}>
          <div style={{ fontFamily:'var(--font-mono)', fontSize:24, fontWeight:500, color:cfg.color, letterSpacing:'-0.02em', lineHeight:1 }}>
            {Math.round(stock.price).toLocaleString()}<span style={{ fontSize:11, color:'var(--text-muted)', marginLeft:3 }}>VTL</span>
          </div>
          <div style={{ fontSize:12, marginTop:4, fontFamily:'var(--font-mono)', color: isUp?'#34D399': isDown?'#F87171':'var(--text-muted)' }}>
            {isUp?'▲':isDown?'▼':'—'} {Math.abs(stock.change_pct).toFixed(2)}%
          </div>
        </div>
      </div>

      <div style={{ fontSize:12, color:'var(--text-secondary)', marginBottom:14, fontStyle:'italic', lineHeight:1.5 }}>
        {cfg.greeting(stock.streak_days)}
      </div>

      <div style={{ marginBottom:16 }}>
        <Sparkline data={stock.sparkline} color={cfg.color} width={280} height={52}/>
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr 1fr', gap:8, marginBottom:16 }}>
        {[
          { label:'Streak', value:`${stock.streak_days}d`, color: stock.streak_days>=7?'#FBBF24':'var(--text-primary)', glow: stock.streak_days>=7 },
          { label:'Peak',   value: Math.round(stock.peak_price||stock.price).toLocaleString(), color:'var(--text-primary)' },
          { label:'Status', value: statusLabel, color: statusColor },
        ].map(m => (
          <div key={m.label} style={{ background:'var(--bg-elevated)', borderRadius:'8px', padding:'10px 12px', border:'1px solid var(--border)', animation: m.glow?'streak-glow 2s ease infinite':'none' }}>
            <div style={{ fontSize:10, color:'var(--text-muted)', letterSpacing:'0.08em', textTransform:'uppercase', marginBottom:4 }}>{m.label}</div>
            <div style={{ fontSize:14, fontWeight:600, color:m.color, fontFamily:m.label==='Status'?'var(--font-body)':'var(--font-mono)' }}>{m.value}</div>
          </div>
        ))}
      </div>

      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center' }}>
        {/* Source badge */}
        {(() => { const src = SOURCE_LABELS[stock.ticker]; return (
          <span style={{ display:'inline-flex', alignItems:'center', gap:5, fontSize:10, fontWeight:600, padding:'3px 8px', borderRadius:20, background:src.bg, color:src.color, border:`1px solid ${src.border}`, letterSpacing:'0.03em' }}>
            <span style={{ width:5, height:5, borderRadius:'50%', background:src.color, display:'inline-block' }}/>
            {src.label}
          </span>
        );})()}
        <div style={{ fontSize:11, fontWeight:600, color:cfg.color, background:cfg.dimColor, padding:'4px 12px', borderRadius:'999px', border:`1px solid ${cfg.borderColor}` }}>
          {expanded ? 'Close ↑' : 'Log activity ↓'}
        </div>
      </div>

      {expanded && (
        <div style={{ marginTop:18, paddingTop:18, borderTop:'1px solid var(--border)', animation:'fadeUp 0.25s ease both' }} onClick={e=>e.stopPropagation()}>
          <div style={{ fontSize:11, color:'var(--text-muted)', marginBottom:10, letterSpacing:'0.06em', textTransform:'uppercase' }}>What did you do?</div>
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:8 }}>
            {acts.map(a => (
              <button key={a.type} disabled={!!logging} onClick={()=>handleLog(a.type)}
                style={{ background: celebrated===a.type ? cfg.dimColor : 'var(--bg-surface)', border:`1px solid ${celebrated===a.type ? cfg.borderColor : 'var(--border)'}`, borderRadius:'8px', padding:'11px 14px', cursor:'pointer', display:'flex', justifyContent:'space-between', alignItems:'center', transition:'all 0.2s', animation: celebrated===a.type?'celebrate 0.6s ease':'none' }}
                onMouseEnter={e=>{e.currentTarget.style.background=cfg.dimColor; e.currentTarget.style.borderColor=cfg.borderColor;}}
                onMouseLeave={e=>{if(celebrated!==a.type){e.currentTarget.style.background='var(--bg-surface)'; e.currentTarget.style.borderColor='var(--border)';}}}
              >
                <div style={{ display:'flex', alignItems:'center', gap:7 }}>
                  <span style={{ fontSize:14 }}>{a.emoji}</span>
                  <span style={{ fontSize:12, color:'var(--text-warm)', fontWeight:500 }}>{logging===a.type?'Logging…':a.label}</span>
                </div>
                <span style={{ fontFamily:'var(--font-mono)', fontSize:11, color:cfg.color, fontWeight:500 }}>{a.vtl}</span>
              </button>
            ))}
            {stock.ticker==='WLT' && (
              <button style={{ gridColumn:'1/-1', background:'rgba(251,191,36,0.05)', border:'1px solid rgba(251,191,36,0.15)', borderRadius:'8px', padding:'11px 14px', cursor:'pointer', display:'flex', justifyContent:'space-between', alignItems:'center', transition:'all 0.2s' }}
                onClick={e=>{e.stopPropagation(); onSync();}}
                onMouseEnter={e=>e.currentTarget.style.background='rgba(251,191,36,0.1)'}
                onMouseLeave={e=>e.currentTarget.style.background='rgba(251,191,36,0.05)'}
              >
                <div style={{ display:'flex', alignItems:'center', gap:7 }}>
                  <span style={{ fontSize:14 }}>🔄</span>
                  <span style={{ fontSize:12, color:'var(--text-warm)', fontWeight:500 }}>Sync Groww portfolio</span>
                </div>
                <span style={{ fontFamily:'var(--font-mono)', fontSize:11, color:'#FBBF24' }}>AUTO</span>
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
